/**
 * High-quality SDF-based text rendering with GPU-accelerated glyph generation.
 *
 * **Architecture**
 * - Multi-channel SDF (Signed Distance Field) atlas for sharp text at any scale
 * - Dynamic glyph packing and layout via `troika-three-text`
 * - TSL node-based material for advanced effects (outlines, fills)
 * - Async `sync()` generates glyphs on-demand with automatic atlas management
 *
 * **Features**
 * - Crisp text rendering at any distance/angle
 * - Fill and outline with independent colors/opacity
 * - Text alignment, wrapping, and layout control
 * - Custom positioning/coloring via TSL node hooks
 * - Efficient instancing for many text instances via `BatchedText`
 *
 * **Events**
 * - `syncstart`: Fired when layout/atlas generation begins
 * - `synccomplete`: Fired when geometry and material are ready
 *
 * ```js
 * import { Text, textLetterId } from '@three-blocks/core';
 * import { sin, positionLocal, Fn } from 'three/tsl';
 *
 * const text = new Text();
 * text.text = 'Hello Three Blocks!';
 * text.fontSize = 0.5;
 * text.color = 0x00ff00;
 * text.anchorX = 'center';
 * text.anchorY = 'middle';
 *
 * // Optional outline
 * text.outlineWidth = '5%';
 * text.outlineColor = 0x000000;
 *
 * scene.add(text);
 *
 * // Custom TSL position hook using standard NodeMaterial API
 * text.material.positionNode = Fn(() => {
 *   const pos = positionLocal.toVar();
 *   pos.y.addAssign(sin(textLetterId.mul(10)).mul(0.1));
 *   return pos;
 * })();
 * ```
 *
 * @class Text
 * @extends THREE.Mesh
 * @tags WebGPU, WebGL
 * @demo docs/demos/text.html
 * @short SDF text mesh with async glyph atlas generation (troika) plus outline/fill controls and TSL hooks.
 * @category Text
 * @fires syncstart
 * @fires synccomplete
 */
export class Text {
    text: string;
    anchorX: number;
    anchorY: number;
    direction: string;
    unicodeFontsURL: any;
    fontSize: number;
    fontWeight: string;
    fontStyle: string;
    lang: any;
    letterSpacing: number;
    lineHeight: string;
    maxWidth: number;
    overflowWrap: string;
    textAlign: string;
    textIndent: number;
    whiteSpace: string;
    material: any;
    color: any;
    colorRanges: any;
    outlineWidth: number;
    outlineColor: number;
    outlineOpacity: number;
    outlineBlur: number;
    outlineOffsetX: number;
    outlineOffsetY: number;
    fillOpacity: number;
    depthOffset: number;
    clipRect: any;
    orientation: string;
    set glyphGeometryDetail(detail: number);
    /**
     * Geometry tessellation detail level (1-3).
     * @type {number}
     */
    get glyphGeometryDetail(): number;
    sdfGlyphSize: any;
    gpuAccelerateSDF: boolean;
    debugSDF: boolean;
    _billboarding: boolean;
    _batchedText: any;
    _visible: boolean;
    uniforms: {
        uThreeBlocksSdfDebug: any;
        uThreeBlocksSDFTextureSize: any;
        uThreeBlocksSDFGlyphSize: any;
        uThreeBlocksSDFExponent: any;
        uThreeBlocksTotalBounds: any;
        uThreeBlocksClipRect: any;
        uThreeBlocksDistanceOffset: any;
        uThreeBlocksOutlineOpacity: any;
        uThreeBlocksFillOpacity: any;
        uThreeBlocksBaseColor: any;
        uThreeBlocksOutlineColor: any;
        uThreeBlocksPositionOffset: any;
        uThreeBlocksBlurRadius: any;
        uThreeBlocksOrient: any;
        uThreeBlocksBillboard: any;
    };
    patchWebGPU(indices: any): Float32Array<any>[];
    /**
     * Trigger asynchronous glyph layout and SDF atlas generation.
     * Called automatically before render if text properties changed.
     *
     * @param {Function} [callback] Called when sync completes.
     * @param {THREE.WebGPURenderer} [renderer] Renderer for GPU SDF generation.
     */
    sync(callback?: Function, renderer?: THREE.WebGPURenderer): void;
    _needsSync: boolean;
    _queuedSyncs: any[];
    _isSyncing: boolean;
    _textRenderInfo: any;
    /**
     * Configure material with TSL nodes for SDF sampling and rendering.
     * Sets up vertex/fragment shaders for both world-space and screen-space modes.
     * @param {THREE.Material} material Target material to configure.
     * @private
     */
    private prepareMaterial;
    sdfMap: any;
    /**
     * Pre-render hook: ensures text is synced and material configured.
     * @param {THREE.WebGPURenderer} renderer
     * @param {THREE.Scene} scene
     * @param {THREE.Camera} camera
     * @param {THREE.BufferGeometry} geometry
     * @param {THREE.Material} material
     */
    onBeforeRender(renderer: THREE.WebGPURenderer, scene: THREE.Scene, camera: THREE.Camera, geometry: THREE.BufferGeometry, material: THREE.Material): void;
    /**
     * Post-render hook: restores material side setting.
     * @param {THREE.WebGPURenderer} renderer
     * @param {THREE.Scene} scene
     * @param {THREE.Camera} camera
     * @param {THREE.BufferGeometry} geometry
     * @param {THREE.Material} material
     */
    onAfterRender(renderer: THREE.WebGPURenderer, scene: THREE.Scene, camera: THREE.Camera, geometry: THREE.BufferGeometry, material: THREE.Material): void;
    /**
     * Dispose of geometry resources.
     */
    dispose(): void;
    /**
     * Get the computed text layout and SDF atlas information.
     * @type {Object|null}
     * @readonly
     */
    readonly get textRenderInfo(): any | null;
    set billboarding(value: boolean);
    /**
     * Enable yaw-only billboarding so text always faces the camera.
     * When enabled, text rotates around the Y-axis to face the camera
     * while remaining upright.
     * @type {boolean}
     */
    get billboarding(): boolean;
    set screenSpace(value: boolean);
    /**
     * Enable screen-space rendering mode where text is positioned in NDC coordinates.
     * When enabled, text position is mapped from layout coordinates to screen pixels
     * using the viewport dimensions, useful for DOM-synchronized text overlays.
     * @type {boolean}
     */
    get screenSpace(): boolean;
    _screenSpace: any;
    _prepareForRender(material: any): Promise<void>;
    _parsePercent(value: any): any;
    localPositionToTextCoords(position: any, target?: any): any;
    worldPositionToTextCoords(position: any, target?: any): any;
    raycast(raycaster: any, intersects: any): void;
    copy(source: any): this;
    geometry: any;
    clone(): any;
}
